return ['domain'=>'nyxify','plural-forms'=>'nplurals=2; plural=(n > 1);','language'=>'fa_IR','project-id-version'=>'Nyxify 1.0.0','pot-creation-date'=>'2026-10-07T06:30:12+00:00','po-revision-date'=>'2026-10-13T20:21:53+00:00','messages'=>['Nyxify – Shop Bots for WooCommerce'=>'Nyxify – ربات‌های فروشگاه برای ووکامرس','Sell your WooCommerce products through Telegram, Bale and Rubika bots.'=>'محصولات فروشگاه ووکامرس خود را با ربات‌های تلگرام، بله و روبیکا بفروشید.','Nyxon'=>'Nyxon','Nyxify is incomplete: its vendor folder is missing. Reinstall the plugin from its release zip.'=>'Nyxify ناقص است: پوشهٔ vendor آن وجود ندارد. افزونه را دوباره از فایل zip انتشار نصب کنید.','Telegram'=>'تلگرام','Bale'=>'بله','Rubika'=>'روبیکا','%s product didn’t reach your bots: your plan’s product limit is reached.'=>'%s محصول به ربات‌ها نرسید: سقف محصولات پلن شما پر شده است.' . "\0" . '%s محصول به ربات‌ها نرسیدند: سقف محصولات پلن شما پر شده است.','Upgrade your plan to include them.'=>'برای افزودن آن‌ها پلن خود را ارتقا دهید.','Last seen %s'=>'آخرین بار: %s','Nyxify settings'=>'تنظیمات Nyxify','Dismiss'=>'بستن','Admin PIN'=>'PIN ادمین','Anyone who sends this PIN to one of your bots becomes a bot admin and can manage your shop from the bot. Share it only with people you trust.'=>'هر کس این PIN را به یکی از ربات‌های شما بفرستد، ادمین ربات می‌شود و می‌تواند فروشگاه شما را از داخل ربات مدیریت کند. آن را فقط به افراد مورد اعتماد بدهید.','No PIN has been issued from this site yet.'=>'هنوز از این سایت PINی صادر نشده است.','A new PIN can be issued here once the store is active and its status can be read.'=>'وقتی فروشگاه فعال باشد و وضعیتش خوانده شود، اینجا می‌توانید PIN جدید بگیرید.','Show'=>'نمایش','Hide'=>'پنهان کردن','Copied'=>'کپی شد','Select the PIN and copy it.'=>'PIN را انتخاب و کپی کنید.','PIN hidden'=>'PIN پنهان است','Copy'=>'کپی','Show PIN'=>'نمایش PIN','The last PIN issued from this site. Issuing a new one makes it stop working.'=>'آخرین PINی که از این سایت صادر شده است. صدور PIN جدید 